import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  configProblems,
  knownKeys,
  localeProblems,
  propertiesKeys,
  structure,
  yamlKeys,
} from './docs-consistency.mjs';

const en = 'documentation/docs/en/';
const zh = 'documentation/docs/zh/';

test('a page has headings by level and code blocks by language, not counting a heading inside a block', () => {
  const page = [
    '---',
    'title: T',
    '---',
    '# Title',
    '## Section',
    '```kotlin',
    '# not a heading',
    '```',
    '### Sub',
    '````md',
    '```ts',
    '```',
    '````',
    '```',
    'plain',
    '```',
  ].join('\n');
  assert.deepEqual(structure(page), {
    headings: [1, 2, 3],
    blocks: ['kotlin', 'md', 'text'],
  });
});

test('the locales are one structure', () => {
  const page = '# A\n## B\n```yaml\nx: 1\n```\n';
  assert.deepEqual(
    localeProblems([
      [`${en}guide/a.md`, page],
      [`${zh}guide/a.md`, '# 甲\n## 乙\n```yaml\nx: 1 # 中文\n```\n'],
    ]),
    [],
  );
  assert.deepEqual(
    localeProblems([
      [`${en}guide/a.md`, page],
      [`${zh}guide/a.md`, '# 甲\n### 乙\n```yml\nx: 1\n```\n'],
    ]),
    [
      `${zh}guide/a.md: headings by level [1,3] differ from the English page's [1,2]`,
      `${zh}guide/a.md: code blocks [yml] differ from the English page's [yaml]`,
    ],
  );
});

test('a page in one locale only is a problem, unless it is generated English', () => {
  assert.deepEqual(
    localeProblems([
      [`${en}guide/a.md`, '# A'],
      [`${zh}guide/b.md`, '# 乙'],
      [
        `${en}reference/symbols.md`,
        '<!-- Generated by scripts/symbol-index.mjs -->\n# Symbols',
      ],
    ]),
    [
      `${zh}guide/a.md: missing; ${en}guide/a.md has no Chinese page`,
      `${en}guide/b.md: missing; ${zh}guide/b.md has no English page`,
    ],
  );
});

test('a YAML block sets the dotted keys that have values', () => {
  assert.deepEqual(
    yamlKeys(
      [
        'spring:',
        '  application:',
        '    name: bank',
        'wow:',
        '  backend: postgres # the log',
        '  kafka:',
        '    bootstrap-servers: localhost:9092',
        '    properties:',
        '      "linger.ms": 5',
        '  aggregates:',
        '    - account',
        '  http:',
        '    errors: |',
        '      a',
      ].join('\n'),
    ),
    [
      'wow.backend',
      'wow.kafka.bootstrap-servers',
      'wow.kafka.properties.linger.ms',
    ],
  );
  assert.deepEqual(
    propertiesKeys('wow.backend=postgres\nspring.x=1\nwow.http.port: 8080'),
    ['wow.backend', 'wow.http.port'],
  );
});

test('a key is known as Spring binds it: a key, a group above keys, or below a map', () => {
  const known = knownKeys([
    { name: 'wow.backend', type: 'java.lang.String' },
    { name: 'wow.kafka.bootstrap-servers', type: 'java.lang.String' },
    {
      name: 'wow.kafka.properties',
      type: 'java.util.Map<java.lang.String,java.lang.String>',
    },
  ]);
  assert.ok(known('wow.backend'));
  assert.ok(known('wow.kafka.bootstrapServers'));
  assert.ok(known('wow.kafka.bootstrap_servers'));
  assert.ok(known('wow.kafka'));
  assert.ok(known('wow.kafka.properties.linger.ms'));
  assert.ok(!known('wow.kafka.bootstrap-servers.extra'));
  assert.ok(!known('wow.dispatch.workers'));
});

test('a configuration block that sets an unknown key fails', () => {
  const known = knownKeys([{ name: 'wow.backend', type: 'java.lang.String' }]);
  const page =
    '```yaml\nwow:\n  backend: postgres\n  shutdown-timeout: 5s\n```\n';
  assert.deepEqual(configProblems('p.md', page, known), [
    'p.md:1: wow.shutdown-timeout is no key of the configuration metadata',
  ]);
});
